CREATE TABLE specialty_protocols(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),code TEXT NOT NULL,service_type TEXT NOT NULL CHECK(service_type IN('contact_lens','ok_lens')),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,code),UNIQUE(id,store_id));

CREATE TABLE specialty_protocol_versions(protocol_id TEXT NOT NULL,store_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>=1),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),title TEXT NOT NULL,institution_scope_note TEXT NOT NULL,professional_duties_note TEXT NOT NULL,assessment_requirement_note TEXT NOT NULL,consent_requirement_note TEXT NOT NULL,parameter_requirement_note TEXT NOT NULL,product_trace_note TEXT NOT NULL,care_requirement_note TEXT NOT NULL,review_requirement_note TEXT NOT NULL,source_note TEXT NOT NULL,source_reference TEXT NOT NULL,require_assessment_evidence INTEGER NOT NULL CHECK(require_assessment_evidence IN(0,1)),require_consent_evidence INTEGER NOT NULL CHECK(require_consent_evidence IN(0,1)),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(protocol_id,version),UNIQUE(protocol_id,version,store_id),FOREIGN KEY(protocol_id,store_id) REFERENCES specialty_protocols(id,store_id));

CREATE TABLE specialty_protocol_events(id TEXT PRIMARY KEY,protocol_id TEXT NOT NULL,store_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>=1),sequence INTEGER NOT NULL CHECK(sequence>=1),version INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN('create','revise','adopt','retire')),status TEXT NOT NULL CHECK(status IN('draft','adopted','retired')),note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(protocol_id,revision),UNIQUE(store_id,sequence),UNIQUE(protocol_id,version,revision,store_id),FOREIGN KEY(protocol_id,version,store_id) REFERENCES specialty_protocol_versions(protocol_id,version,store_id));

CREATE TABLE specialty_cases(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,protocol_id TEXT NOT NULL,protocol_version INTEGER NOT NULL,protocol_revision INTEGER NOT NULL,cycle_id TEXT NOT NULL,cycle_version INTEGER NOT NULL,visit_id TEXT REFERENCES visits(id),context_basis TEXT NOT NULL CHECK(context_basis IN('cycle','visit_cycle')),serial INTEGER NOT NULL CHECK(serial>=1),case_number TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(id,store_id,customer_id),UNIQUE(store_id,serial),FOREIGN KEY(customer_id,store_id) REFERENCES customers(id,store_id),FOREIGN KEY(protocol_id,protocol_version,protocol_revision,store_id) REFERENCES specialty_protocol_events(protocol_id,version,revision,store_id),FOREIGN KEY(cycle_id,cycle_version,customer_id) REFERENCES cycle_versions(cycle_id,version,customer_id),CHECK((context_basis='cycle' AND visit_id IS NULL) OR(context_basis='visit_cycle' AND visit_id IS NOT NULL)));

CREATE TABLE specialty_case_versions(case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>=1),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),title TEXT NOT NULL,assessment_note TEXT NOT NULL,suitability_note TEXT NOT NULL,source_note TEXT NOT NULL,next_step TEXT NOT NULL,suitability TEXT NOT NULL CHECK(suitability IN('pending','needs_more','not_suitable','suitable')),assessed_at TEXT,document_ids_json TEXT NOT NULL CHECK(json_valid(document_ids_json)),attachment_ids_json TEXT NOT NULL CHECK(json_valid(attachment_ids_json)),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(case_id,version),UNIQUE(case_id,version,store_id,customer_id),FOREIGN KEY(case_id,store_id,customer_id) REFERENCES specialty_cases(id,store_id,customer_id),CHECK((suitability='pending' AND assessed_at IS NULL) OR(suitability!='pending' AND assessed_at IS NOT NULL)));

CREATE TABLE specialty_case_events(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>=1),sequence INTEGER NOT NULL CHECK(sequence>=1),version INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN('create','revise','assign','adopt','pause','resume','stop')),status TEXT NOT NULL CHECK(status IN('draft','active','paused','stopped')),owner_id TEXT NOT NULL REFERENCES users(id),consent_id TEXT REFERENCES specialty_consents(id),consent_revision INTEGER,next_step TEXT NOT NULL,note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(case_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(case_id,store_id,customer_id) REFERENCES specialty_cases(id,store_id,customer_id),FOREIGN KEY(case_id,version) REFERENCES specialty_case_versions(case_id,version),FOREIGN KEY(consent_id,consent_revision,case_id,store_id,customer_id) REFERENCES specialty_consent_events(consent_id,revision,case_id,store_id,customer_id),CHECK((consent_id IS NULL AND consent_revision IS NULL) OR(consent_id IS NOT NULL AND consent_revision IS NOT NULL)));

CREATE TABLE specialty_consents(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,case_version INTEGER NOT NULL,initial_case_revision INTEGER NOT NULL,party TEXT NOT NULL CHECK(party IN('patient','guardian')),party_label TEXT NOT NULL,relationship_note TEXT NOT NULL,signed_at TEXT NOT NULL,source_note TEXT NOT NULL,document_ids_json TEXT NOT NULL CHECK(json_valid(document_ids_json)),attachment_ids_json TEXT NOT NULL CHECK(json_valid(attachment_ids_json)),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(id,case_id,store_id,customer_id),FOREIGN KEY(case_id,store_id,customer_id) REFERENCES specialty_cases(id,store_id,customer_id),FOREIGN KEY(case_id,case_version) REFERENCES specialty_case_versions(case_id,version),FOREIGN KEY(case_id,initial_case_revision) REFERENCES specialty_case_events(case_id,revision));

CREATE TABLE specialty_consent_events(id TEXT PRIMARY KEY,consent_id TEXT NOT NULL,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>=1),sequence INTEGER NOT NULL CHECK(sequence>=1),action TEXT NOT NULL CHECK(action IN('grant','revoke')),status TEXT NOT NULL CHECK(status IN('active','revoked')),occurred_at TEXT NOT NULL,note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(consent_id,revision),UNIQUE(store_id,sequence),UNIQUE(consent_id,revision,case_id,store_id,customer_id),FOREIGN KEY(consent_id,case_id,store_id,customer_id) REFERENCES specialty_consents(id,case_id,store_id,customer_id));

CREATE VIEW specialty_protocol_current AS SELECT e.* FROM specialty_protocol_events e WHERE e.revision=(SELECT max(revision) FROM specialty_protocol_events WHERE protocol_id=e.protocol_id);

CREATE VIEW specialty_case_current AS SELECT e.* FROM specialty_case_events e WHERE e.revision=(SELECT max(revision) FROM specialty_case_events WHERE case_id=e.case_id);

CREATE VIEW specialty_consent_current AS SELECT e.* FROM specialty_consent_events e WHERE e.revision=(SELECT max(revision) FROM specialty_consent_events WHERE consent_id=e.consent_id);

CREATE VIEW specialty_journal AS SELECT store_id,sequence,created_at,'protocol' kind,protocol_id root_id,id FROM specialty_protocol_events UNION ALL SELECT store_id,sequence,created_at,'case',case_id,id FROM specialty_case_events UNION ALL SELECT store_id,sequence,created_at,'consent',consent_id,id FROM specialty_consent_events;

CREATE TRIGGER specialty_protocols_no_update BEFORE UPDATE ON specialty_protocols BEGIN SELECT RAISE(ABORT,'specialty immutable history'); END;

CREATE TRIGGER specialty_protocols_no_delete BEFORE DELETE ON specialty_protocols BEGIN SELECT RAISE(ABORT,'specialty immutable history'); END;

CREATE TRIGGER specialty_protocols_actor BEFORE INSERT ON specialty_protocols WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN('manager','reception','professional')) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.created_by AND role='manager') BEGIN SELECT RAISE(ABORT,'specialty source/state mismatch'); END;

CREATE TRIGGER specialty_protocol_versions_no_update BEFORE UPDATE ON specialty_protocol_versions BEGIN SELECT RAISE(ABORT,'specialty immutable history'); END;

CREATE TRIGGER specialty_protocol_versions_no_delete BEFORE DELETE ON specialty_protocol_versions BEGIN SELECT RAISE(ABORT,'specialty immutable history'); END;

CREATE TRIGGER specialty_protocol_versions_actor BEFORE INSERT ON specialty_protocol_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN('manager','reception','professional')) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.created_by AND role='manager') BEGIN SELECT RAISE(ABORT,'specialty source/state mismatch'); END;

