CREATE TRIGGER specialty_case_versions_no_delete BEFORE DELETE ON specialty_case_versions BEGIN SELECT RAISE(ABORT,'specialty immutable history'); END;

CREATE TRIGGER specialty_case_versions_actor BEFORE INSERT ON specialty_case_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND u.role IN('manager','reception','professional')) OR length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at BEGIN SELECT RAISE(ABORT,'specialty source/state mismatch'); END;

